/**
 * International trust anchors — selected major CAs, trusted only when the
 * user turns on "trust selected international CAs" (default: Taiwan only).
 *
 * Same pipeline as the Taiwan roots: DER files + manifest under
 * scripts/trust-store/, pinned by SHA-256, regenerated by
 * build-trust-store.mjs. Each entry names its vendor and whether it anchors
 * document signing, timestamping, or both.
 *
 * While the option is off these roots are still offered to the path builder,
 * so a signature under them is reported as "international CA, not enabled"
 * instead of an unknown root.
 */
import { GENERATED_ROOTS } from './generated-anchors'
import type { TrustAnchorEntry } from './taiwan-roots'

export const INTERNATIONAL_ROOT_CERTIFICATES: TrustAnchorEntry[] = GENERATED_ROOTS.filter(
  (entry) => entry.category === 'international'
)

/** Vendors of the bundled international roots, for the settings text. */
export function getInternationalVendors(): string[] {
  return [...new Set(INTERNATIONAL_ROOT_CERTIFICATES.map((entry) => entry.vendor ?? entry.name))]
}
